// src/modules/work/work-insights.service.ts
//
// Serviço de insights do módulo Work
// Implementa lógica de análise e performance

import {
  getLatestSummaries,
  getJobHistory,
  getPerformanceScore,
  getWorkPatterns,
  type WorkSummary,
  type JobHistoryEntry,
  type PerformanceScore,
  type WorkPatterns,
} from './work.insights';

class WorkInsightsService {
  /**
   * Retorna resumo das últimas sessões de trabalho
   */
  async getSummary(tenantId: string, userId: string, limit: number = 5): Promise<WorkSummary[]> {
    return await getLatestSummaries(userId, limit);
  }

  /**
   * Retorna histórico de jobs do usuário
   */
  async getHistory(tenantId: string, userId: string, limit: number = 20): Promise<JobHistoryEntry[]> {
    return await getJobHistory(userId, limit);
  }

  /**
   * Calcula e retorna score de performance
   */
  async getPerformance(tenantId: string, userId: string): Promise<PerformanceScore> {
    return await getPerformanceScore(userId);
  }

  /**
   * Detecta e retorna padrões de trabalho
   */
  async getPatterns(tenantId: string, userId: string): Promise<WorkPatterns> {
    return await getWorkPatterns(userId);
  }
}

export const workInsightsService = new WorkInsightsService();
















